INSERT OR IGNORE INTO posts (id, title_id, user_id, category, body, quote_character, quote_note, spoiler, season, episode, created_at, updated_at, removed) VALUES ('p3', 't-interstellar', 'u-sana', 'moment', 'The video messages scene. Twenty-three years of messages in a few minutes. I had to pause it.', NULL, NULL, 1, NULL, NULL, '2026-10-13T21:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO posts (id, title_id, user_id, category, body, quote_character, quote_note, spoiler, season, episode, created_at, updated_at, removed) VALUES ('p4', 't-interstellar', 'u-tom', 'trailer_thought', 'The cornfield shots alone sold me. Quiet trailers are the best trailers.', NULL, NULL, 0, NULL, NULL, '2026-10-10T08:00:00.000Z', NULL, 0);
