INSERT OR IGNORE INTO posts (id, title_id, user_id, category, body, quote_character, quote_note, spoiler, season, episode, created_at, updated_at, removed) VALUES ('p8', 't-breaking-bad', 'u-tom', 'quote', 'I am the one who knocks.', 'Walter White', 'The moment the mask fell off for good.', 0, 4, 6, '2026-10-11T20:00:00.000Z', NULL, 0);
