INSERT OR IGNORE INTO posts (id, title_id, user_id, category, body, quote_character, quote_note, spoiler, season, episode, created_at, updated_at, removed) VALUES ('p11', 't-past-lives', 'u-amara', 'lesson', 'You can love who you were and still be grateful for who you became.', NULL, NULL, 0, NULL, NULL, '2026-10-14T22:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO posts (id, title_id, user_id, category, body, quote_character, quote_note, spoiler, season, episode, created_at, updated_at, removed) VALUES ('p12', 't-the-bear', 'u-leo', 'moment', 'The one-take kitchen episode made my heart rate genuinely go up. I needed a walk after.', NULL, NULL, 0, 1, 7, '2026-10-13T10:00:00.000Z', NULL, 0);
