INSERT OR IGNORE INTO posts (id, title_id, user_id, category, body, quote_character, quote_note, spoiler, season, episode, created_at, updated_at, removed) VALUES ('p15', 't-dark', 'u-tom', 'moment', 'The first time the caves are opened. Pure dread, in the best way.', NULL, NULL, 0, 1, 1, '2026-10-10T19:00:00.000Z', NULL, 0);
