INSERT OR IGNORE INTO reviews (id, title_id, user_id, heading, body, spoiler, created_at, updated_at, removed) VALUES ('r1', 't-interstellar', 'u-leo', 'A film about time, really about parents', 'I went in expecting a space movie and came out thinking about my dad.

Under all the physics, Interstellar is about the cost of leaving and the promise of coming back. The docking scene is spectacular, but what stayed with me was how much of the film is just people waiting for each other.

Not every line of dialogue lands, and the third act asks you to go along with a lot. I didn''t mind. It made me want to call home.', 0, '2026-10-13T12:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO reviews (id, title_id, user_id, heading, body, spoiler, created_at, updated_at, removed) VALUES ('r2', 't-interstellar', 'u-amara', NULL, 'The soundtrack carried me through the whole thing. The organ makes everything feel like a cathedral. I''m not a science person and I still followed the feelings perfectly.', 0, '2026-10-12T17:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO reviews (id, title_id, user_id, heading, body, spoiler, created_at, updated_at, removed) VALUES ('r3', 't-parasite', 'u-sana', 'The staircase never stops going down', 'Every set in Parasite is about height. Up the hill, down the stairs, below the basement. By the end, I was noticing every step.

It''s funny for a long time, then it isn''t, and the switch happens so smoothly you only notice after.', 1, '2026-10-11T14:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO reviews (id, title_id, user_id, heading, body, spoiler, created_at, updated_at, removed) VALUES ('r4', 't-breaking-bad', 'u-tom', 'Slow, then all at once', 'The first season is quieter than people remember. I loved that. It lets you believe Walt is a good man for just long enough.', 0, '2026-10-10T12:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO questions (id, title_id, user_id, text, details, spoiler, season, episode, created_at, updated_at, removed) VALUES ('q1', 't-interstellar', 'u-tom', 'How did Cooper end up inside the tesseract?', 'I understood the black hole part, but who built it, and why could he only reach that bookshelf?', 1, NULL, NULL, '2026-10-14T09:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO questions (id, title_id, user_id, text, details, spoiler, season, episode, created_at, updated_at, removed) VALUES ('q2', 't-arrival', 'u-amara', 'Was Louise choosing her future, or just remembering it?', NULL, 1, NULL, NULL, '2026-10-13T08:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO questions (id, title_id, user_id, text, details, spoiler, season, episode, created_at, updated_at, removed) VALUES ('q3', 't-dark', 'u-leo', 'Is there a good way to keep track of the family trees on a first watch?', 'Three episodes in and I''m already lost. No spoilers please!', 0, NULL, NULL, '2026-10-12T20:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO answers (id, question_id, user_id, body, spoiler, helpful, created_at, updated_at, removed) VALUES ('a1', 'q1', 'u-leo', 'The film suggests future humans built the tesseract so Cooper could communicate with Murph through gravity. The bookshelf is where his strongest connection to her lived, which is why that''s where it opens.', 1, 1, '2026-10-14T12:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO answers (id, question_id, user_id, body, spoiler, helpful, created_at, updated_at, removed) VALUES ('a2', 'q1', 'u-sana', 'I read it as love being the thing that tunes him to the right moment. Not literally, but emotionally it''s the bridge.', 1, 0, '2026-10-14T15:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO answers (id, question_id, user_id, body, spoiler, helpful, created_at, updated_at, removed) VALUES ('a3', 'q3', 'u-sana', 'Keep a little notebook with each family name at the top of a page. Write down who is related to whom as you learn it. Don''t look up charts — they spoil things.', 0, 0, '2026-10-13T09:00:00.000Z', NULL, 0);
INSERT OR IGNORE INTO replies (id, target_type, target_id, user_id, body, spoiler, created_at, removed) VALUES ('rp1', 'post', 'p1', 'u-leo', 'This is the whole movie in one sentence.', 0, '2026-10-15T10:00:00.000Z', 0);
