INSERT OR IGNORE INTO replies (id, target_type, target_id, user_id, body, spoiler, created_at, removed) VALUES ('rp3', 'answer', 'a1', 'u-tom', 'Ah, that makes the bookshelf make sense. Thank you.', 0, '2026-10-14T13:00:00.000Z', 0);
