"Comedy","Drama"],"hue":350,"synopsis":"A sharp, grieving woman navigates life and love in London while talking directly to us about all of it.","country":"United Kingdom","language":"English","people":[{"name":"Phoebe Waller-Bridge","role":"creator"},{"name":"Phoebe Waller-Bridge","role":"cast","character":"Fleabag"},{"name":"Sian Clifford","role":"cast","character":"Claire"},{"name":"Andrew Scott","role":"cast","character":"The Priest"}]},{"status":"published","createdAt":"2026-09-01T10:00:00.000Z","id":"t-eeaao","slug":"everything-everywhere-all-at-once-2022","kind":"movie","name":"Everything Everywhere All at Once","altNames":["EEAAO"],"year":2022,"genres":["Science Fiction","Comedy","Action"],"hue":310,"synopsis":"An exhausted laundromat owner discovers she must connect with versions of herself across the multiverse to save what matters.","runtime":"2h 19m","country":"United States","language":"English","people":[{"name":"Daniel Kwan","role":"director"},{"name":"Daniel Scheinert","role":"director"},{"name":"Michelle Yeoh","role":"cast","character":"Evelyn Wang"},{"name":"Ke Huy Quan","role":"cast","character":"Waymond Wang"}]},{"status":"published","createdAt":"2026-09-01T10:00:00.000Z","id":"t-coco","slug":"coco-2017","kind":"movie","name":"Coco","altNames":[],"year":2017,"genres":["Animation","Family","Music"],"hue":40,"synopsis":"A young musician crosses into the Land of the Dead to uncover the story behind his family''s ban on music.","runtime":"1h 45m","country":"United States","language":"English","people":[{"name":"Lee Unkrich","role":"director"},{"name":"Anthony Gonzalez","role":"cast","character":"Miguel"},{"name":"Gael García Bernal","role":"cast","character":"Héctor"}]},{"status":"published","createdAt":"2026-09-01T10:00:00.000Z","id":"t-the-bear","slug":"the-bear-2022","kind":"series","name":"The Bear","altNames":[],"year":2022,"genres":["Drama","Comedy"],"hue":25,"synopsis":"A young fine-dining chef returns home to run his late brother''s chaotic sandwich shop in Chicago.","country":"United States","language":"English","people":[{"name":"Christopher Storer","role":"creator"},{"name":"Jeremy Allen White","role":"cast","character":"Carmy Berzatto"},{"name":"Ayo Edebiri","role":"cast","character":"Sydney Adamu"}]},{"status":"published","createdAt":"2026-09-01T10:00:00.000Z","id":"t-past-lives","slug":"past-lives-2023","kind":"movie","name":"Past Lives","altNames":[],"year":2023,"genres":["Romance","Drama"],"hue":180,"synopsis":"Two childhood friends separated by emigration reunite decades later and confront the lives they didn''t live.","runtime":"1h 46m","country":"United States","language":"English, Korean","people":[{"name":"Celine Song","role":"director"},{"name":"Greta Lee","role":"cast","character":"Nora"},{"name":"Teo Yoo","role":"cast","character":"Hae Sung"}]}],"discoveryTags":[{"id":"tag-former-pilots","name":"Former Pilots","slug":"former-pilots","description":"Stories about pilots who leave the cockpit behind.","aliases":["ex-pilots","retired aviators"],"createdAt":"2026-10-01T12:00:00.000Z","updatedAt":"2026-10-01T12:00:00.000Z"},{"id":"tag-family-separation","name":"Family Separation","slug":"family-separation","description":"Stories shaped by distance, absence, or the fear of losing family.","aliases":["leaving children behind","separated families"],"createdAt":"2026-10-01T12:00:00.000Z","updatedAt":"2026-10-01T12:00:00.000Z"},{"id":"tag-dangerous-missions","name":"Dangerous Missions","slug":"dangerous-missions","description":"Characters risking everything to complete an impossible mission.","aliases":["perilous missions","impossible missions"],"createdAt":"2026-10-01T12:00:00.000Z","updatedAt":"2026-10-01T12:00:00.000Z"},{"id":"tag-crossing-worlds","name":"Crossing Worlds","slug":"crossing-worlds","description":"Stories where a character steps into a strange or hidden world.","aliases":["other worlds","parallel worlds"],"createdAt":"2026-10-01T12:00:00.000Z","updatedAt":"2026-10-01T12:00:00.000Z"}],"titleDiscoveryTags":[{"titleId":"t-interstellar","tagId":"tag-former-pilots","createdAt":"2026-10-01T12:00:00.000Z"},{"titleId":"t-interstellar","tagId":"tag-family-separation","createdAt":"2026-10-01T12:00:00.000Z"},{"titleId":"t-interstellar","tagId":"tag-dangerous-missions","createdAt":"2026-10-01T12:00:00.000Z"},{"titleId":"t-arrival","tagId":"tag-dangerous-missions","createdAt":"2026-10-01T12:00:00.000Z"},{"titleId":"t-spirited-away","tagId":"tag-crossing-worlds","createdAt":"2026-10-01T12:00:00.000Z"},{"titleId":"t-eeaao","tagId":"tag-crossing-worlds","createdAt":"2026-10-01T12:00:00.000Z"},{"titleId":"t-dark","tagId":"tag-family-separation","createdAt":"2026-10-01T12:00:00.000Z"}],"intentLinks":[{"id":"intent-interstellar-pilot","titleId":"t-interstellar","tagId":"tag-former-pilots","selectedPhrase":"former pilot","startOffset":39,"endOffset":51,"blurbVersion":"seed","approvalStatus":"approved","createdAt":"2026-10-01T12:00:00.000Z","updatedAt":"2026-10-01T12:00:00.000Z"},{"id":"intent-interstellar-family","titleId":"t-interstellar","tagId":"tag-family-separation","selectedPhrase":"leaves his children behind","startOffset":52,"endOffset":78,"blurbVersion":"seed","approvalStatus":"approved","createdAt":"2026-10-01T12:00:00.000Z","updatedAt":"2026-10-01T12:00:00.000Z"}],"posts":[{"id":"p1","titleId":"t-interstellar","userId":"u-amara","category":"lesson","body":"Love isn''t a distraction from the mission. Sometimes it is the mission.","spoiler":false,"createdAt":"2026-10-15T09:00:00.000Z"},{"id":"p2","titleId":"t-interstellar","userId":"u-leo","category":"quote","body":"Do not go gentle into that good night.","quoteCharacter":"Professor Brand","quoteNote":"Hearing a poem read like a launch countdown never leaves you.","spoiler":false,"createdAt":"2026-10-14T18:00:00.000Z"},{"id":"p3","titleId":"t-interstellar","userId":"u-sana","category":"moment","body":"The video messages scene. Twenty-three years of messages in a few minutes. I had to pause it.","spoiler":true,"createdAt":"2026-10-13T21:00:00.000Z"},{"id":"p4","titleId":"t-interstellar","userId":"u-tom","category":"trailer_thought","body":"The cornfield shots alone sold me. Quiet trailers are the best trailers.","spoiler":false,"createdAt":"2026-10-10T08:00:00.000Z"},{"id":"p5","titleId":"t-spirited-away","userId":"u-amara","category":"lesson","body":"Remembering your own name is a kind of freedom. Don''t let work or other people take it from you.","spoiler":false,"createdAt":"2026-10-15T07:00:00.000Z"},{"id":"p6","titleId":"t-spirited-away","userId":"u-sana","category":"moment","body":"The train across the flooded sea. No dialogue, just watching the world go by. Perfect stillness.","spoiler":false,"createdAt":"2026-10-12T15:00:00.000Z"},{"id":"p7","titleId":"t-breaking-bad","userId":"u-leo","category":"lesson","body":"Pride is the most expensive thing a person can own.","spoiler":false,"createdAt":"2026-10-14T11:00:00.000Z"},{"id":"p8","titleId":"t-breaking-bad","userId":"u-tom","category":"quote","body":"I am the one who knocks.","quoteCharacter":"Walter White","quoteNote":"The moment the mask fell off for good.","spoiler":false,"season":4,"episode":6,"createdAt":"2026-10-11T20:00:00.000Z"},{"id":"p9","titleId":"t-arrival","userId":"u-sana","category":"lesson","body":"Knowing how something ends doesn''t mean you shouldn''t begin it.","spoiler":true,"createdAt":"2026-10-15T06:00:00.000Z"},{"id":"p10","titleId":"t-shawshank","userId":"u-tom","category":"quote","body":"Get busy living, or get busy dying.","quoteCharacter":"Andy Dufresne","spoiler":false,"createdAt":"2026-10-09T13:00:00.000Z"},{"id":"p11","titleId":"t-past-lives","userId":"u-amara","category":"lesson","body":"You can love who you were and still be grateful for who you became.","spoiler":false,"createdAt":"2026-10-14T22:00:00.000Z"},{"id":"p12","titleId":"t-the-bear","userId":"u-leo","category":"moment","body":"The one-take kitchen episode made my heart rate genuinely go up. I needed a walk after.","spoiler":false,"season":1,"episode":7,"createdAt":"2026-10-13T10:00:00.000Z"},{"id":"p13","titleId":"t-coco","userId":"u-sana","category":"lesson","body":"We stay alive in the stories people keep telling about us. Call your grandparents.","spoiler":false,"createdAt":"2026-10-12T09:00:00.000Z"},{"id":"p14","titleId":"t-eeaao","userId":"u-amara","category":"quote","body":"Please, be kind. Especially when we don''t know what''s going on.","quoteCharacter":"Waymond Wang","spoiler":false,"createdAt":"2026-10-11T16:00:00.000Z"},{"id":"p15","titleId":"t-dark","userId":"u-tom","category":"moment","body":"The first time the caves are opened. Pure dread, in the best way.","spoiler":false,"season":1,"episode":1,"createdAt":"2026-10-10T19:00:00.000Z"},{"id":"p16","titleId":"t-fleabag","userId":"u-leo","category":"lesson","body":"Humour is often how people keep the door shut. Fleabag taught me to notice when I''m doing it.","spoiler":false,"createdAt":"2026-10-09T09:00:00.000Z"}],"reviews":[{"id":"r1","titleId":"t-interstellar","userId":"u-leo","heading":"A film about time, really about parents","body":"I went in expecting a space movie and came out thinking about my dad.\n\nUnder all the physics, Interstellar is about the cost of leaving and the promise of coming back. The docking scene is spectacular, but what stayed with me was how much of the film is just people waiting for each other.\n\nNot every line of dialogue lands, and the third act asks you to go along with a lot. I didn''t mind. It made me want to call home.","spoiler":false,"createdAt":"2026-10-13T12:00:00.000Z"},{"id":"r2","titleId":"t-interstellar","userId":"u-amara","body":"The soundtrack carried me through the whole thing. The organ makes everything feel like a cathedral. I''m not a science person and I still followed the feelings perfectly.","spoiler":false,"createdAt":"2026-10-12T17:00:00.000Z"},{"id":"r3","titleId":"t-parasite","userId":"u-sana","heading":"The staircase never stops going down","body":"Every set in Parasite is about height. Up the hill, down the stairs, below the basement. By the end, I was noticing every step.\n\nIt''s funny for a long time, then it isn''t, and the switch happens so smoothly you only notice after.","spoiler":true,"createdAt":"2026-10-11T14:00:00.000Z"},{"id":"r4","titleId":"t-breaking-bad","userId":"u-tom","heading":"Slow, then all at once","body":"The first season is quieter than people remember. I loved that. It lets you believe Walt is a good man for just long enough.","spoiler":false,"createdAt":"2026-10-10T12:00:00.000Z"}],"questions":[{"id":"q1","titleId":"t-interstellar","userId":"u-tom","text":"How did Cooper end up inside the tesseract?","details":"I understood the black hole part, but who built it, and why could he only reach that bookshelf?","spoiler":true,"createdAt":"2026-10-14T09:00:00.000Z"},{"id":"q2","titleId":"t-arrival","userId":"u-amara","text":"Was Louise choosing her future, or just remembering it?","spoiler":true,"createdAt":"2026-10-13T08:00:00.000Z"},{"id":"q3","titleId":"t-dark","userId":"u-leo","text":"Is there a good way to keep track of the family trees on a first watch?","details":"Three episodes in and I''m already lost. No spoilers please!","spoiler":false,"createdAt":"2026-10-12T20:00:00.000Z"}],"answers":[{"id":"a1","questionId":"q1","userId":"u-leo","body":"The film suggests future humans built the tesseract so Cooper could communicate with Murph through gravity. The bookshelf is where his strongest connection to her lived, which is why that''s where it opens.","spoiler":true,"helpful":true,"createdAt":"2026-10-14T12:00:00.000Z"},{"id":"a2","questionId":"q1","userId":"u-sana","body":"I read it as love being the thing that tunes him to the right moment. Not literally, but emotionally it''s the bridge.","spoiler":true,"helpful":false,"createdAt":"2026-10-14T15:00:00.000Z"},{"id":"a3","questionId":"q3","userId":"u-sana","body":"Keep a little notebook with each family name at the top of a page. Write down who is related to whom as you learn it. Don''t look up charts — they spoil things.","spoiler":false,"helpful":false,"createdAt":"2026-10-13T09:00:00.000Z"}],"replies":[{"id":"rp1","targetType":"post","targetId":"p1","userId":"u-leo","body":"This is the whole movie in one sentence.","spoiler":false,"createdAt":"2026-10-15T10:00:00.000Z"},{"id":"rp2","targetType":"review","targetId":"r1","userId":"u-amara","body":"Same. I called my mum right after.","spoiler":false,"createdAt":"2026-10-13T19:00:00.000Z"},{"id":"rp3","targetType":"answer","targetId":"a1","userId":"u-tom","body":"Ah, that makes the bookshelf make sense. Thank you.","spoiler":false,"createdAt":"2026-10-14T13:00:00.000Z"}],"likes":[{"userId":"u-leo","targetType":"post","targetId":"p1"},{"userId":"u-sana","targetType":"post","targetId":"p1"},{"userId":"u-tom","targetType":"post","targetId":"p1"},{"userId":"u-amara","targetType":"post","targetId":"p2"},{"userId":"u-amara","targetType":"review","targetId":"r1"},{"userId":"u-tom","targetType":"review","targetId":"r1"},{"userId":"u-tom","targetType":"answer","targetId":"a1"},{"userId":"u-amara","targetType":"answer","targetId":"a1"},{"userId":"u-leo","targetType":"post","targetId":"p5"},{"userId":"u-tom","targetType":"post","targetId":"p14"}],"collections":[{"id":"c1","slug":"movies-that-taught-me-something","userId":"u-amara","name":"Movies That Taught Me Something","description":"Small lessons, big feelings.","titleIds":["t-spirited-away","t-coco","t-past-lives","t-interstellar","t-shawshank"],"createdAt":"2026-10-05T12:00:00.000Z","updatedAt":"2026-10-14T12:00:00.000Z"},{"id":"c2","slug":"my-favorite-mystery-stories","userId":"u-leo","name":"My Favorite Mystery Stories","description":"Puzzles worth getting lost in.","titleIds":["t-dark","t-arrival","t-parasite"],"createdAt":"2026-10-06T12:00:00.000Z","updatedAt":"2026-10-12T12:00:00.000Z"},{"id":"c3","slug":"series-with-unforgettable-endings","userId":"u-tom","name":"Series With Unforgettable Endings","titleIds":["t-breaking-bad","t-fleabag","t-dark"],"createdAt":"2026-10-07T12:00:00.000Z","updatedAt":"2026-10-11T12:00:00.000Z"}],"savedCollections":[{"userId":"u-sana","collectionId":"c1"}],"library":[{"userId":"u-amara","titleId":"t-interstellar","state":"watched","updatedAt":"2026-10-12T12:00:00.000Z"},{"userId":"u-amara","titleId":"t-dark","state":"want","updatedAt":"2026-10-12T12:00:00.000Z"}],"trail":[],"reports":[{"id":"rep1","targetType":"post","targetId":"p8","reporterId":"u-sana","reason":"Possible spoiler without a warning","status":"open","createdAt":"2026-10-12T08:00:00.000Z"}],"modActions":[],"recommendations":[],"slugRedirects":{},"sessionUserId":null}') ON CONFLICT(id) DO UPDATE SET payload = excluded.payload, updated_at = CURRENT_TIMESTAMP;
